// ─────────────────────────────────────────────────────────────────────────────
// PLATFORM-SCOPE MANAGERS — the OS's OWN AI operators, staff-facing, never on the
// tenant bus. The tenant-facing team above is deliberately LOCKED at 14 seats
// (test:doc-kernel pins Object.keys(MANAGERS).length === 14, and ManagerKey feeds
// the agent_kind / manager_signals vocabularies) — so the Platform Sentinel is NOT
// a 15th tenant seat: it watches the SUBSCRIBER FLEET for platform staff (round 21:
// engagement risk, expiring connections, dunning, SLA breaches, expiring trials →
// severity-ranked proposals with drafted outreach; round 22: it LEARNS from staff
// verdicts). Registered here with the SAME identity contract as the tenant team
// (label/domain/accent owned by the registry) so the staff surfaces render a named
// manager persona instead of hand-kept prose — no drift, no unregistered ghost.
// Its schedule (/api/cron/platform-sentinel) and its proposals ledger
// (platform_sentinel_actions) stay data_steward-owned in CRON_MANAGER/TABLE_MANAGER:
// the steward RUNS the sweep; this entry is the PERSONA the fleet work is attributed to.
// ─────────────────────────────────────────────────────────────────────────────
export type PlatformManagerKey = "platform_sentinel"

export interface PlatformManagerInfo {
  key:    PlatformManagerKey
  label:  string
  /** One-line domain the platform manager is accountable for (staff UI tooltip). */
  domain: string
  /** Tailwind accent for the identity chip on staff surfaces — registry-owned. */
  accent: string
}

export const PLATFORM_MANAGERS: Record<PlatformManagerKey, PlatformManagerInfo> = {
  platform_sentinel: { key: "platform_sentinel", label: "Platform Sentinel", domain: "Subscriber-fleet health — daily staff action proposals (platform scope)", accent: "bg-stone-200 text-stone-800" },
}

/** Resolve a platform-scope manager's identity (staff surfaces; never undefined). */
export function resolvePlatformManager(key: string): PlatformManagerInfo {
  return (key in PLATFORM_MANAGERS)
    ? PLATFORM_MANAGERS[key as PlatformManagerKey]
    : { key: "platform_sentinel", label: "Platform Operations", domain: "Unassigned platform-scope work — needs an owner", accent: "bg-slate-100 text-slate-700" }
}

// ─────────────────────────────────────────────────────────────────────────────
// CROSS-MANAGEMENT (round 34 — "managers should be working together and can
// cross manage"): the DECLARED COLLABORATION MAP. Single-ownership stays the
// law (TABLE_MANAGER / QUEUE_MANAGER / CRON_MANAGER are untouched — one steward
// per table, one owner per queue), but the REAL overlaps where two managers
// already co-work a domain are now first-class instead of implicit. Every entry
// below is DERIVED from evidence that already exists in this registry + the
// signal catalog (catalogued bus signals, stewarded tables, queue ownership) —
// no aspirational edges. The cross_manager_referral signal (SIGNAL_REGISTRY)
// may ONLY travel along these declared edges: the shared referral handler
// refuses any from→to pair that no collaboration domain contains, so
// cross-management is governed by this map, never a free-for-all.
// Pure data (no I/O) — safe for the client governance surface to render.
// ─────────────────────────────────────────────────────────────────────────────

export interface CollaborationDomain {
  key: string
  /** Human label for the co-managed domain (governance surface). */
  label: string
  /** The co-managers of this shared domain. A referral edge is valid only when
   *  BOTH ends appear in the same entry. */
  managers: ManagerKey[]
  /** The REAL overlap this entry encodes — the catalogued signals / stewarded
   *  tables / queue ownership that prove these managers already co-work it. */
  evidence: string
  /** DELIBERATIVE domain (round 35 — "the managers should also argue a solution and
   *  work through the reason why that solution is the best for the situation"): a
   *  referral on this domain escalates to a full DELIBERATION — each co-manager argues
   *  a grounded position from its own domain facts, a resolution pass picks the winner
   *  with the stated why, and honest dissent is recorded (lib/managers/deliberation.ts).
   *  Set ONLY where the real overlap is a genuine TRADEOFF two managers can reasonably
   *  disagree on (pricing disputes, budget rebalances, compliance-vs-speed) — a plain
   *  handoff/nag domain stays non-deliberative: there is nothing to argue. */
  deliberate?: boolean
}

